/**
 * Both SilentCipher variants, end to end through the ONNX/WASM decoder.
 *
 * Samples are generated by tools/make_samples.py on a synthesised, never-watermarked
 * carrier, so each one provably carries only the watermark we embedded:
 *
 *   44k1_* : the real upstream encode_wav() with Irodori's payload "IRDTS"
 *   16k_*  : a raw 15-symbol word (the only layout that model can represent); the
 *            encoder used is verified bit-for-bit against encode_wav() on 44.1 kHz
 *
 * The cross-variant checks matter: a watermark from one model must not be reported by
 * the detector for the other.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';

import { prepare, runDetector } from '../web/src/pipeline.js';
import { VARIANTS, getVariant } from '../web/src/detector.js';
import { ROOT, decodePcm, getSession, Tensor } from './helpers.mjs';

const SAMPLES = path.join(ROOT, 'test', 'samples');
const slug = { '44.1k': '44k1', '16k': '16k' };

function meta(variant) {
  const p = path.join(SAMPLES, `${slug[variant]}_samples.json`);
  return existsSync(p) ? JSON.parse(readFileSync(p, 'utf8')) : null;
}
const sample = (variant, name) => path.join(SAMPLES, `${slug[variant]}_${name}`);
const have = (variant) => meta(variant) !== null;

async function analyse(file, variant, { maxSeconds = 12, earlyStop = false } = {}) {
  const cfg = getVariant(variant);
  const spec = prepare(decodePcm(file, 48000), 48000, cfg);
  const session = await getSession(variant);
  const { result } = await runDetector(spec, session, Tensor, {
    cfg,
    chunkFrames: 43,
    maxFrames: Math.min(spec.frames, Math.round((maxSeconds * cfg.sampleRate) / cfg.hopLength)),
    earlyStop,
    inputName: session.inputNames[0],
    outputName: session.outputNames[0],
  });
  return result;
}

const fmt = (r) => `${r.variant} verdict=${r.verdict} struct=${r.structure.toFixed(3)}`
  + (r.bytePayload ? ` margin=${r.margin.toFixed(3)} p=${r.pValue.toExponential(1)}` : '')
  + ` frames=${r.frames} conf=${r.blind.confidence.toFixed(3)}`
  + ` out=${r.blind.ascii ?? (r.blind.symbols ? `[${r.blind.symbols.join(',')}]` : 'null')}`;

/* ------------------------------------------------------------ 44.1 kHz ------ */

test('44.1k: detects the Irodori payload in a freshly watermarked sample',
  { timeout: 1800000, skip: !have('44.1k') }, async () => {
    const th = VARIANTS['44.1k'].thresholds;
    const r = await analyse(sample('44.1k', 'watermarked.wav'), '44.1k');
    console.log(`    ${fmt(r)}`);
    assert.equal(r.verdict, 'detected');
    assert.ok(r.margin >= th.detectMargin, `margin=${r.margin}`);
    assert.ok(r.pValue <= th.detectP, `p=${r.pValue}`);
    assert.equal(r.blind.ascii, 'IRDTS', 'payload must come back byte-exact');
    assert.deepEqual(r.blind.message, meta('44.1k').payload);
    assert.equal(r.payloadExact, true);
  });

test('44.1k: survives an Opus round trip',
  { timeout: 1800000, skip: !have('44.1k') }, async () => {
    const r = await analyse(sample('44.1k', 'watermarked.webm'), '44.1k');
    console.log(`    ${fmt(r)}`);
    assert.equal(r.verdict, 'detected');
  });

test('44.1k: the unwatermarked carrier is rejected',
  { timeout: 1800000, skip: !have('44.1k') }, async () => {
    const r = await analyse(sample('44.1k', 'clean.wav'), '44.1k');
    console.log(`    ${fmt(r)}`);
    assert.notEqual(r.verdict, 'detected');
    assert.notEqual(r.blind.ascii, 'IRDTS');
  });

/* -------------------------------------------------------------- 16 kHz ------ */

test('16k: detects a genuine 16 kHz watermark payload-independently',
  { timeout: 1800000, skip: !have('16k') }, async () => {
    const th = VARIANTS['16k'].thresholds;
    const r = await analyse(sample('16k', 'watermarked.wav'), '16k');
    console.log(`    ${fmt(r)}`);
    assert.equal(r.verdict, 'detected');
    assert.equal(r.bytePayload, false);
    assert.ok(r.structure >= th.detectStructure, `structure=${r.structure}`);
    assert.deepEqual(r.blind.symbols, meta('16k').message_symbols);
    assert.equal(r.blind.message, null, 'this variant yields no bytes');
    assert.equal(r.match, null, 'and no payload-matched statistic');
  });

test('16k: survives an Opus round trip',
  { timeout: 1800000, skip: !have('16k') }, async () => {
    const r = await analyse(sample('16k', 'watermarked.webm'), '16k');
    console.log(`    ${fmt(r)}`);
    assert.equal(r.verdict, 'detected');
  });

test('16k: the unwatermarked carrier is rejected',
  { timeout: 1800000, skip: !have('16k') }, async () => {
    const r = await analyse(sample('16k', 'clean.wav'), '16k');
    console.log(`    ${fmt(r)}`);
    assert.notEqual(r.verdict, 'detected');
  });

/* -------------------------------------------------------- cross-variant ----- */

test('a 16 kHz watermark is not reported by the 44.1 kHz detector',
  { timeout: 1800000, skip: !(have('16k') && have('44.1k')) }, async () => {
    const r = await analyse(sample('16k', 'watermarked.wav'), '44.1k');
    console.log(`    ${fmt(r)}`);
    assert.notEqual(r.verdict, 'detected');
  });

test('a 44.1 kHz watermark is not reported by the 16 kHz detector',
  { timeout: 1800000, skip: !(have('16k') && have('44.1k')) }, async () => {
    const r = await analyse(sample('44.1k', 'watermarked.wav'), '16k');
    console.log(`    ${fmt(r)}`);
    assert.notEqual(r.verdict, 'detected');
  });
